	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void invalidShapeRejectsBeforeNativeCapacityFault(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = smallMapConfig();
		RetryProbe probe = new RetryProbe();
		CountingLmdbStore store = new CountingLmdbStore(directory.toFile(), config, probe);
		CountingShaclSail shacl = new CountingShaclSail(store, probe);
		SailRepository repository = new SailRepository(shacl);
		Statement typeStatement = VF.createStatement(PERSON, RDF.TYPE, PERSON_TYPE, DATA_CONTEXT);
		Statement invalidAge = VF.createStatement(PERSON, AGE, Values.literal("not an integer"), DATA_CONTEXT);
		AtomicInteger notifications = new AtomicInteger();
		RepositoryException validationFailure = null;
		Set<Statement> reopenedStatements = Set.of();
		String reopenedNamespace = null;

		try {
			repository.init();
			try (SailRepositoryConnection shapes = repository.getConnection()) {
				addPersonShape(shapes);
			}
			probe.reset();
			shacl.resetPrepareCalls();
			probe.capacityFailureBudget.set(1);
			store.addSailChangedListener(event -> notifications.incrementAndGet());
			try (SailRepositoryConnection writer = repository.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT_READ);
				writer.add(typeStatement.getSubject(), typeStatement.getPredicate(), typeStatement.getObject(),
						DATA_CONTEXT);
				writer.add(invalidAge.getSubject(), invalidAge.getPredicate(), invalidAge.getObject(), DATA_CONTEXT);
				writer.setNamespace("rejected", "urn:m3:rejected:");
				try {
					writer.commit();
				} catch (RepositoryException failure) {
					validationFailure = failure;
				}
			}
		} finally {
			repository.shutDown();
		}

		SailRepository reopened = new SailRepository(new LmdbStore(directory.toFile(), config));
		try {
			reopened.init();
			try (RepositoryConnection reader = reopened.getConnection()) {
				reopenedStatements = readDataStatements(reader);
				reopenedNamespace = reader.getNamespace("rejected");
			}
		} finally {
			reopened.shutDown();
		}

		RepositoryException observedValidationFailure = validationFailure;
		Set<Statement> observedReopenedStatements = reopenedStatements;
		String observedReopenedNamespace = reopenedNamespace;
		assertAll("invalid SHACL data is rejected before native capacity recovery starts",
				() -> assertNotNull(observedValidationFailure,
						"the invalid datatype must fail SHACL validation"),
				() -> assertTrue(hasCauseNamed(observedValidationFailure, "ShaclSailValidationException"),
						"the failure must originate in actual SHACL validation"),
				() -> assertEquals(1, shacl.prepareCalls(),
						"the invalid input must reach the single application prepare callback"),
				() -> assertEquals(0, probe.nativeCapacityFailures.get(),
						"the invalid transaction must be rejected before consuming the native fault"),
				() -> assertEquals(1, probe.capacityFailureBudget.get(),
						"the real native fault must remain armed and unused after validation rejects"),
				() -> assertEquals(0, probe.rowsAtCapacityFailure.get(),
						"no application rows may reach the native failure boundary"),
				() -> assertEquals(0, notifications.get(),
						"an invalid transaction must not emit a logical commit notification"),
				() -> assertTrue(observedReopenedStatements.isEmpty(),
						"the invalid transaction must leave no application statements after reopening"),
				() -> assertNull(observedReopenedNamespace,
						"the invalid transaction namespace must remain unpublished after reopening"));
	}

	private static void addPersonShape(RepositoryConnection connection) {
		Resource shape = Values.bnode("PersonShape");
		Resource ageShape = Values.bnode("PersonAgeShape");
		connection.begin();
		connection.add(shape, RDF.TYPE, SHACL.NODE_SHAPE, RDF4J.SHACL_SHAPE_GRAPH);
		connection.add(shape, SHACL.TARGET_CLASS, PERSON_TYPE, RDF4J.SHACL_SHAPE_GRAPH);
		connection.add(shape, SHACL.PROPERTY, ageShape, RDF4J.SHACL_SHAPE_GRAPH);
		connection.add(ageShape, SHACL.PATH, AGE, RDF4J.SHACL_SHAPE_GRAPH);
		connection.add(ageShape, SHACL.MIN_COUNT, Values.literal(1), RDF4J.SHACL_SHAPE_GRAPH);
		connection.add(ageShape, SHACL.DATATYPE, XSD.INTEGER, RDF4J.SHACL_SHAPE_GRAPH);
		connection.commit();
	}

	private static Set<Statement> readDataStatements(RepositoryConnection connection) {
		Set<Statement> statements = new HashSet<>();
		try (RepositoryResult<Statement> result = connection.getStatements(null, null, null, false, DATA_CONTEXT)) {
			while (result.hasNext()) {
				statements.add(result.next());
			}
		}
		return Set.copyOf(statements);
	}

	private static boolean hasCauseNamed(Throwable failure, String simpleName) {
		for (Throwable current = failure; current != null; current = current.getCause()) {
			if (current.getClass().getSimpleName().equals(simpleName)) {
				return true;
			}
		}
		return false;
	}

